import React from 'react';
import ComparisonCharts from './ComparisonCharts';
import { Card, Alert, Row, Col, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';

const SimulationDashboard = ({ results }) => {
    const navigate = useNavigate();

    if (!results) {
        return (
            <Alert variant="info">No simulation results yet. Please run the simulation first.</Alert>
        );
    }

    return (
        <>
            <Card className="mb-4">
                <Card.Header as="h2">Simulation Dashboard</Card.Header>
                <Card.Body>
                    <Row className="mb-3">
                        <Col>
                            <Card>
                                <Card.Body>
                                    <Card.Title>Average Lifetime</Card.Title>
                                    <Card.Text>{results.average_lifetime} steps</Card.Text>
                                </Card.Body>
                            </Card>
                        </Col>
                        <Col>
                            <Card>
                                <Card.Body>
                                    <Card.Title>Total Energy</Card.Title>
                                    <Card.Text>{results.total_energy} units</Card.Text>
                                </Card.Body>
                            </Card>
                        </Col>
                    </Row>

                    <ComparisonCharts results={results} />
                    <div className="mt-3 text-center">
                        <Button variant="secondary" onClick={() => navigate('/')}>Run Again</Button>{' '}
                        <Button variant="primary" onClick={() => navigate('/comparison')}>View Chart</Button>
                    </div>
                </Card.Body>
            </Card>
        </>
    );
};

export default SimulationDashboard;
